// Token-level lexer: turns shell source text into a flat list of fine-grained
// tokens.  Quoting state is carried by QOpen/QClose tokens; expansions,
// command substitutions and backticks recurse into their own sub-lists.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ExpKind {
    Var,
    Brace,
    CmdSub,
    Backtick,
    Arith,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum QKind {
    Single,
    Double,
    Ansi,
    Locale,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    Sep,
    Nl,
    Comment,
    Heredoc,
    Op,
    Lit,
    Esc,
    Exp(ExpKind),
    QOpen(QKind),
    QClose(QKind),
    QText,
}

#[derive(Clone, Debug)]
pub struct Tok {
    pub kind: Kind,
    pub text: String,
    pub sub: Vec<Tok>,
}

impl Tok {
    pub fn new(kind: Kind, text: &str) -> Tok {
        Tok { kind, text: text.to_string(), sub: Vec::new() }
    }
    pub fn new_sub(kind: Kind, text: &str, sub: Vec<Tok>) -> Tok {
        Tok { kind, text: text.to_string(), sub }
    }
}

#[derive(Debug)]
pub struct LexErr;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Stop {
    Eof,
    Paren,
    Backtick,
    Ansi,
    Quote(QKind),
}

fn is_id_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == '\t'
}

fn is_op_start(c: char) -> bool {
    matches!(c, ';' | '|' | '&' | '<' | '>')
}

pub struct Lex {
    cs: Vec<char>,
    pos: usize,
}

impl Lex {
    pub fn new(src: &str) -> Lex {
        Lex { cs: src.chars().collect(), pos: 0 }
    }

    fn cur(&self) -> Option<char> {
        self.cs.get(self.pos).copied()
    }
    fn at(&self, n: usize) -> Option<char> {
        self.cs.get(self.pos + n).copied()
    }
    fn slice(&self, a: usize, b: usize) -> String {
        self.cs[a..b].iter().collect()
    }
    fn take(&mut self, n: usize) -> String {
        let s = self.slice(self.pos, self.pos + n);
        self.pos += n;
        s
    }

    pub fn top(&mut self) -> Result<Vec<Tok>, LexErr> {
        let mut out = Vec::new();
        self.until(Stop::Eof, &mut out)?;
        Ok(out)
    }

    fn until(&mut self, stop: Stop, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        let mut paren_depth: i32 = 0;
        loop {
            if self.pos >= self.cs.len() {
                if stop != Stop::Eof {
                    return Err(LexErr);
                }
                return Ok(());
            }
            let c = self.cur().unwrap();
            match c {
                '\n' => {
                    out.push(Tok::new(Kind::Nl, "\n"));
                    self.pos += 1;
                }
                '\r' if self.at(1) == Some('\n') => {
                    out.push(Tok::new(Kind::Nl, "\r\n"));
                    self.pos += 2;
                }
                c if is_ws(c) => {
                    let start = self.pos;
                    while self.pos < self.cs.len() && is_ws(self.cs[self.pos]) {
                        self.pos += 1;
                    }
                    out.push(Tok::new(Kind::Sep, &self.slice(start, self.pos)));
                }
                '#' => {
                    let start = self.pos;
                    while self.pos < self.cs.len() && self.cs[self.pos] != '\n' {
                        self.pos += 1;
                    }
                    out.push(Tok::new(Kind::Comment, &self.slice(start, self.pos)));
                }
                ';' | '|' | '&' | '<' | '>' => {
                    let s = self.slice(self.pos, self.pos + 3);
                    let matched = if s.starts_with("<<<") {
                        "<<<"
                    } else if s.starts_with("<<-") {
                        "<<-"
                    } else if s.starts_with("<<") {
                        "<<"
                    } else if s.starts_with(">>") {
                        ">>"
                    } else if s.starts_with(">&") {
                        ">&"
                    } else if s.starts_with("<&") {
                        "<&"
                    } else if s.starts_with("&&") {
                        "&&"
                    } else if s.starts_with("||") {
                        "||"
                    } else if s.starts_with("|&") {
                        "|&"
                    } else if s.starts_with(";;") {
                        ";;"
                    } else if s.starts_with(";") {
                        ";"
                    } else if s.starts_with("|") {
                        "|"
                    } else if s.starts_with("&") {
                        "&"
                    } else if s.starts_with(">") {
                        ">"
                    } else {
                        "<"
                    };
                    let n = matched.chars().count();
                    out.push(Tok::new(Kind::Op, matched));
                    self.pos += n;
                }
                '(' => {
                    paren_depth += 1;
                    out.push(Tok::new(Kind::Op, "("));
                    self.pos += 1;
                }
                ')' => {
                    if stop == Stop::Paren && paren_depth == 0 {
                        return Ok(());
                    }
                    if paren_depth > 0 {
                        paren_depth -= 1;
                    }
                    out.push(Tok::new(Kind::Op, ")"));
                    self.pos += 1;
                }
                '`' => {
                    if stop == Stop::Backtick {
                        return Ok(());
                    }
                    self.backtick(out)?;
                }
                '\\' => {
                    let n = 2;
                    out.push(Tok::new(Kind::Esc, &self.take(n)));
                }
                '$' => {
                    self.dollar(stop, out)?;
                }
                '\'' => {
                    out.push(Tok::new(Kind::QOpen(QKind::Single), "'"));
                    self.pos += 1;
                    self.until(Stop::Quote(QKind::Single), out)?;
                    out.push(Tok::new(Kind::QClose(QKind::Single), "'"));
                    self.pos += 1;
                }
                '"' => {
                    let qk = match stop {
                        Stop::Ansi => QKind::Ansi,
                        _ => QKind::Double,
                    };
                    out.push(Tok::new(Kind::QOpen(qk), "\""));
                    self.pos += 1;
                    self.until(if qk == QKind::Ansi { Stop::Eof } else { Stop::Quote(QKind::Double) }, out)?;
                    out.push(Tok::new(Kind::QClose(qk), "\""));
                    self.pos += 1;
                }
                _ => {
                    // literal text
                    let start = self.pos;
                    while self.pos < self.cs.len() {
                        let ch = self.cs[self.pos];
                        if ch == '\n'
                            || ch == '\r'
                            || is_ws(ch)
                            || ch == '#'
                            || is_op_start(ch)
                            || ch == '('
                            || ch == ')'
                            || ch == '`'
                            || ch == '\\'
                            || ch == '$'
                            || ch == '\''
                            || ch == '"'
                        {
                            break;
                        }
                        self.pos += 1;
                    }
                    if self.pos == start {
                        return Err(LexErr);
                    }
                    out.push(Tok::new(Kind::Lit, &self.slice(start, self.pos)));
                }
            }
        }
    }

    fn quoted(&mut self, qk: QKind, stop: Stop, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        // content of a quoted string
        loop {
            if self.pos >= self.cs.len() {
                return Err(LexErr);
            }
            let c = self.cur().unwrap();
            let close = if qk == QKind::Ansi { '\'' } else { '"' };
            if c == close {
                return Ok(());
            }
            if qk == QKind::Single {
                // raw content
                let start = self.pos;
                while self.pos < self.cs.len() && self.cs[self.pos] != '\'' {
                    self.pos += 1;
                }
                out.push(Tok::new(Kind::QText, &self.slice(start, self.pos)));
                continue;
            }
            if c == '\\' {
                out.push(Tok::new(Kind::Esc, &self.take(2)));
                continue;
            }
            if qk != QKind::Ansi && c == '$' {
                self.dollar(stop, out)?;
                continue;
            }
            if qk != QKind::Ansi && c == '`' {
                self.backtick(out)?;
                continue;
            }
            let start = self.pos;
            while self.pos < self.cs.len() {
                let ch = self.cs[self.pos];
                if ch == close || ch == '\\' || (qk != QKind::Ansi && (ch == '$' || ch == '`')) {
                    break;
                }
                self.pos += 1;
            }
            out.push(Tok::new(Kind::QText, &self.slice(start, self.pos)));
        }
    }

    fn backtick(&mut self, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        let start = self.pos;
        out.push(Tok::new(Kind::Op, "`"));
        self.pos += 1;
        let mut sub = Vec::new();
        self.until(Stop::Backtick, &mut sub)?;
        if self.cur() != Some('`') {
            return Err(LexErr);
        }
        self.pos += 1;
        let text = self.slice(start, self.pos);
        out.push(Tok::new_sub(Kind::Exp(ExpKind::Backtick), &text, sub));
        Ok(())
    }

    fn dollar(&mut self, stop: Stop, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        match self.at(1) {
            Some('\'') => {
                // ANSI-C string  $'...'
                out.push(Tok::new(Kind::QOpen(QKind::Ansi), "$'"));
                self.pos += 2;
                self.quoted(QKind::Ansi, stop, out)?;
                out.push(Tok::new(Kind::QClose(QKind::Ansi), "'"));
                self.pos += 1;
            }
            Some('(') => {
                if self.at(2) == Some('(') {
                    let start = self.pos;
                    let mut depth: i32 = 2;
                    self.pos += 3;
                    while self.pos < self.cs.len() {
                        let ch = self.cs[self.pos];
                        if ch == '(' {
                            depth += 1;
                        } else if ch == ')' {
                            depth -= 1;
                            if depth == 0 {
                                break;
                            }
                        }
                        self.pos += 1;
                    }
                    if depth != 0 {
                        return Err(LexErr);
                    }
                    let text = self.slice(start, self.pos);
                    self.pos += 1;
                    out.push(Tok::new(Kind::Exp(ExpKind::Arith), &text));
                } else {
                    let start = self.pos;
                    self.pos += 2;
                    let mut sub = Vec::new();
                    self.until(Stop::Paren, &mut sub)?;
                    if self.cur() != Some(')') {
                        return Err(LexErr);
                    }
                    self.pos += 1;
                    let text = self.slice(start, self.pos);
                    out.push(Tok::new_sub(Kind::Exp(ExpKind::CmdSub), &text, sub));
                }
            }
            Some('{') => {
                let start = self.pos;
                let mut depth: i32 = 0;
                self.pos += 1;
                while self.pos < self.cs.len() {
                    let ch = self.cs[self.pos];
                    if ch == '{' {
                        depth += 1;
                    } else if ch == '}' {
                        if depth == 0 {
                            break;
                        }
                        depth -= 1;
                    }
                    self.pos += 1;
                }
                if self.cur() != Some('}') {
                    return Err(LexErr);
                }
                self.pos += 1;
                let text = self.slice(start, self.pos);
                out.push(Tok::new(Kind::Exp(ExpKind::Brace), &text));
            }
            Some('"') => {
                out.push(Tok::new(Kind::Exp(ExpKind::Var), "$"));
                self.pos += 1;
                out.push(Tok::new(Kind::QOpen(QKind::Locale), "\""));
                self.pos += 1;
                self.quoted(QKind::Locale, stop, out)?;
                out.push(Tok::new(Kind::QClose(QKind::Locale), "\""));
                self.pos += 1;
            }
            Some(c) => {
                if is_id_char(c)
                    || c == '-'
                    || c == '@'
                    || c == '*'
                    || c == '?'
                    || c == '!'
                    || c == '$'
                    || c == '#'
                {
                    let start = self.pos;
                    self.pos += 2;
                    if self.cur().map(is_id_char).unwrap_or(false) {
                        while self.pos < self.cs.len() && is_id_char(self.cs[self.pos]) {
                            self.pos += 1;
                        }
                    }
                    let text = self.slice(start, self.pos);
                    out.push(Tok::new(Kind::Exp(ExpKind::Var), &text));
                } else {
                    out.push(Tok::new(Kind::Lit, "$"));
                    self.pos += 1;
                }
            }
            None => {
                out.push(Tok::new(Kind::Lit, "$"));
                self.pos += 1;
            }
        }
        Ok(())
    }
}
