                    let start = self.pos;
                    while self.pos < self.cs.len() && self.cs[self.pos] != '\n' {
                        self.pos += 1;
                    }
                    out.push(Tok::new(Kind::Comment, &self.slice(start, self.pos)));
                }
                ';' | '|' | '&' | '<' | '>' => {
                    if let Some(op) = self.operator() {
                        out.push(Tok::new(Kind::Op, &op));
                        self.pos += op.chars().count();
                        if op == "<<" || op == "<<-" {
                            self.heredoc(&op, out)?;
                        }
                    } else {
                        return Err(LexErr);
                    }
                }
                '(' => {
                    paren_depth += 1;
                    out.push(Tok::new(Kind::Op, "("));
                    self.pos += 1;
                }
                ')' => {
                    if stop == Stop::Paren && paren_depth == 0 {
                        return Ok(());
                    }
                    if paren_depth > 0 {
                        paren_depth -= 1;
                    }
                    out.push(Tok::new(Kind::Op, ")"));
                    self.pos += 1;
                }
                '`' => {
                    if stop == Stop::Backtick {
                        return Ok(());
                    }
                    self.backtick(out)?;
                }
                '\\' => {
                    out.push(Tok::new(Kind::Esc, &self.take(2)));
                }
                '$' => {
                    self.dollar(stop, out)?;
                }
                '\'' => {
                    out.push(Tok::new(Kind::QOpen(QKind::Single), "'"));
                    self.pos += 1;
                    self.quoted(QKind::Single, out)?;
                    out.push(Tok::new(Kind::QClose(QKind::Single), "'"));
                    self.pos += 1;
                }
                '"' => {
                    out.push(Tok::new(Kind::QOpen(QKind::Double), "\""));
                    self.pos += 1;
                    self.quoted(QKind::Double, out)?;
                    out.push(Tok::new(Kind::QClose(QKind::Double), "\""));
                    self.pos += 1;
                }
                _ => {
                    // literal text
                    let start = self.pos;
                    while self.pos < self.cs.len() {
                        let ch = self.cs[self.pos];
                        if ch == '\n'
                            || ch == '\r'
                            || is_ws(ch)
                            || ch == '#'
                            || is_op_start(ch)
                            || ch == '('
                            || ch == ')'
                            || ch == '`'
                            || ch == '\\'
                            || ch == '$'
                            || ch == '\''
                            || ch == '"'
                        {
                            break;
                        }
                        self.pos += 1;
                    }
                    if self.pos == start {
                        return Err(LexErr);
                    }
                    out.push(Tok::new(Kind::Lit, &self.slice(start, self.pos)));
                }
            }
        }
    }

    fn operator(&self) -> Option<&'static str> {
        let s3: String = self.slice(self.pos, (self.pos + 3).min(self.cs.len()));
        let s2: String = self.slice(self.pos, (self.pos + 2).min(self.cs.len()));
        let c = self.cur()?;
        Some(match c {
            '<' => {
                if s3.starts_with("<<<") {
                    "<<<"
                } else if s3.starts_with("<<-") {
                    "<<-"
                } else if s2.starts_with("<<") {
                    "<<"
                } else if s2.starts_with("<&") {
                    "<&"
                } else {
                    "<"
                }
            }
            '>' => {
                if s2.starts_with(">>") {
                    ">>"
                } else if s2.starts_with(">&") {
                    ">&"
                } else {
                    ">"
                }
            }
            ';' => {
                if s3.starts_with(";;&") {
                    ";;&"
                } else if s2.starts_with(";;") {
                    ";;"
                } else {
                    ";"
                }
            }
            '|' => {
                if s2.starts_with("||") {
                    "||"
                } else if s2.starts_with("|&") {
                    "|&"
                } else {
                    "|"
                }
            }
            '&' => {
                if s2.starts_with("&&") {
                    "&&"
                } else {
                    "&"
                }
            }
            _ => return None,
        })
    }

    /// Handle a heredoc start that was just emitted as an `<<`/`<<-` operator.
    fn heredoc(&mut self, op: &str, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        let char_start = self.pos - op.chars().count();
        let out_start = out.len() - 1;
        // look ahead for a delimiter token
        let mut p = self.pos;
        while p < self.cs.len() && (is_ws(self.cs[p]) || self.cs[p] == '\n') {
            p += 1;
        }
        if p >= self.cs.len() {
            // no delimiter: not a heredoc
            return Ok(());
        }
        // consume whitespace / newlines as tokens, they will be merged
        while self.pos < self.cs.len() && (is_ws(self.cs[self.pos]) || self.cs[self.pos] == '\n') {
            let c = self.cs[self.pos];
            if c == '\n' {
                out.push(Tok::new(Kind::Nl, "\n"));
            } else {
                let start = self.pos;
                while self.pos < self.cs.len() && is_ws(self.cs[self.pos]) {
                    self.pos += 1;
                }
                out.push(Tok::new(Kind::Sep, &self.slice(start, self.pos)));
            }
        }
        // parse the delimiter token group
        let mut del: Vec<Tok> = Vec::new();
        match self.cur() {
            Some('\'') => {
                del.push(Tok::new(Kind::QOpen(QKind::Single), "'"));
                self.pos += 1;
                self.quoted(QKind::Single, &mut del)?;
                del.push(Tok::new(Kind::QClose(QKind::Single), "'"));
                self.pos += 1;
            }
            Some('"') => {
                del.push(Tok::new(Kind::QOpen(QKind::Double), "\""));
                self.pos += 1;
                self.quoted(QKind::Double, &mut del)?;
                del.push(Tok::new(Kind::QClose(QKind::Double), "\""));
                self.pos += 1;
            }
            Some('$') => {
                self.dollar(Stop::Eof, &mut del)?;
            }
            Some('`') => {
                self.backtick(&mut del)?;
            }
            Some('\\') => {
                del.push(Tok::new(Kind::Esc, &self.take(2)));
            }
            Some('#') => {
                let start = self.pos;
                while self.pos < self.cs.len() && self.cs[self.pos] != '\n' {
                    self.pos += 1;
                }
                del.push(Tok::new(Kind::Comment, &self.slice(start, self.pos)));
            }
            _ => {
                let start = self.pos;
                while self.pos < self.cs.len() {
                    let ch = self.cs[self.pos];
                    if ch == '\n'
                        || ch == '\r'
                        || is_ws(ch)
                        || ch == '#'
                        || is_op_start(ch)
                        || ch == '('
                        || ch == ')'
                        || ch == '`'
                        || ch == '\\'
                        || ch == '$'
                        || ch == '\''
                        || ch == '"'
                    {
                        break;
                    }
                    self.pos += 1;
                }
                del.push(Tok::new(Kind::Lit, &self.slice(start, self.pos)));
            }
        }
        let mut value = String::new();
        for t in &del {
            match t.kind {
                Kind::QOpen(_) | Kind::QClose(_) => {}
                Kind::QText | Kind::Lit | Kind::Op | Kind::Comment | Kind::Heredoc => {
                    value.push_str(&t.text)
                }
                Kind::Esc => value.push_str(&t.text),
                Kind::Exp(_) | Kind::Sep | Kind::Nl => value.push_str(&t.text),
            }
        }
        // find the delimiter in the remaining text
        let mut idx: Option<usize> = None;
        let n = value.chars().count();
        if n > 0 {
            let mut i = self.pos;
            while i + n <= self.cs.len() {
                if self.slice(i, i + n) == value {
                    idx = Some(i);
                    break;
                }
                i += 1;
            }
        }
        let end = match idx {
            Some(i) => i + n,
            None => self.cs.len(),
        };
        let text = self.slice(char_start, end);
        out.truncate(out_start);
        out.push(Tok::new(Kind::Heredoc, &text));
        self.pos = end;
        if idx.is_none() {
            return Err(LexErr);
        }
        Ok(())
    }

    /// Content of a quoted string; stops (without consuming) at the close char.
    fn quoted(&mut self, qk: QKind, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        let close = if qk == QKind::Ansi { '\'' } else { '"' };
        loop {
            if self.pos >= self.cs.len() {
                return Err(LexErr);
            }
            let c = self.cur().unwrap();
            if c == close {
                return Ok(());
            }
            if qk == QKind::Single {
                let start = self.pos;
                while self.pos < self.cs.len() && self.cs[self.pos] != '\'' {
                    self.pos += 1;
                }
                out.push(Tok::new(Kind::QText, &self.slice(start, self.pos)));
                continue;
            }
            if c == '\\' {
                out.push(Tok::new(Kind::Esc, &self.take(2)));
                continue;
            }
            if qk != QKind::Ansi {
                if c == '$' {
                    self.dollar(Stop::Eof, out)?;
                    continue;
                }
                if c == '`' {
                    self.backtick(out)?;
                    continue;
                }
            }
            let start = self.pos;
            while self.pos < self.cs.len() {
                let ch = self.cs[self.pos];
                if ch == close || ch == '\\' || (qk != QKind::Ansi && (ch == '$' || ch == '`')) {
                    break;
                }
                self.pos += 1;
            }
            out.push(Tok::new(Kind::QText, &self.slice(start, self.pos)));
        }
    }

    fn backtick(&mut self, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        let start = self.pos;
        self.pos += 1;
        let mut sub: Vec<Tok> = Vec::new();
        self.until(Stop::Backtick, &mut sub)?;
        if self.cur() != Some('`') {
            return Err(LexErr);
        }
        self.pos += 1;
        let text = self.slice(start, self.pos);
        out.push(Tok::new_sub(Kind::Exp(ExpKind::Backtick), &text, sub));
        Ok(())
    }

    fn dollar(&mut self, stop: Stop, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        match self.at(1) {
            Some('\'') => {
                out.push(Tok::new(Kind::QOpen(QKind::Ansi), "$'"));
                self.pos += 2;
                self.quoted(QKind::Ansi, out)?;
                out.push(Tok::new(Kind::QClose(QKind::Ansi), "'"));
                self.pos += 1;
            }
            Some('(') => {
                if self.at(2) == Some('(') {
                    let start = self.pos;
                    let mut depth: i32 = 2;
                    self.pos += 3;
                    while self.pos < self.cs.len() {
                        let ch = self.cs[self.pos];
                        if ch == '(' {
                            depth += 1;
                        } else if ch == ')' {
                            depth -= 1;
                            if depth == 0 {
                                break;
                            }
                        }
                        self.pos += 1;
                    }
                    if depth != 0 {
                        return Err(LexErr);
                    }
                    let text = self.slice(start, self.pos);
                    self.pos += 1;
                    out.push(Tok::new(Kind::Exp(ExpKind::Arith), &text));
                } else {
                    let start = self.pos;
                    self.pos += 2;
                    let mut sub: Vec<Tok> = Vec::new();
                    self.until(Stop::Paren, &mut sub)?;
                    if self.cur() != Some(')') {
                        return Err(LexErr);
                    }
                    self.pos += 1;
                    let text = self.slice(start, self.pos);
                    out.push(Tok::new_sub(Kind::Exp(ExpKind::CmdSub), &text, sub));
                }
            }
            Some('{') => {
                let start = self.pos;
                let mut depth: i32 = 0;
                self.pos += 1;
                while self.pos < self.cs.len() {
                    let ch = self.cs[self.pos];
                    if ch == '{' {
                        depth += 1;
                    } else if ch == '}' {
                        if depth == 0 {
                            break;
                        }
                        depth -= 1;
                    }
                    self.pos += 1;
                }
                if self.cur() != Some('}') {
                    return Err(LexErr);
                }
                self.pos += 1;
                let text = self.slice(start, self.pos);
                out.push(Tok::new(Kind::Exp(ExpKind::Brace), &text));
            }
            Some('"') => {
                out.push(Tok::new(Kind::Exp(ExpKind::Var), "$"));
                self.pos += 1;
                out.push(Tok::new(Kind::QOpen(QKind::Locale), "\""));
                self.pos += 1;
                self.quoted(QKind::Locale, out)?;
                out.push(Tok::new(Kind::QClose(QKind::Locale), "\""));
                self.pos += 1;
            }
            Some(c) => {
                if is_id_char(c)
                    || c == '-'
                    || c == '@'
                    || c == '*'
                    || c == '?'
                    || c == '!'
                    || c == '$'
                    || c == '#'
                {
                    let start = self.pos;
                    self.pos += 2;
                    if self.cur().map(is_id_char).unwrap_or(false) {
                        while self.pos < self.cs.len() && is_id_char(self.cs[self.pos]) {
                            self.pos += 1;
                        }
                    }
                    let text = self.slice(start, self.pos);
                    out.push(Tok::new(Kind::Exp(ExpKind::Var), &text));
                } else {
                    out.push(Tok::new(Kind::Lit, "$"));
                    self.pos += 1;
                }
            }
            None => {
                out.push(Tok::new(Kind::Lit, "$"));
                self.pos += 1;
            }
        }
        Ok(())
    }
}
