// Token-level lexer: turns shell source text into a flat list of fine-grained
// tokens.  Quoting state is carried by QOpen/QClose tokens; expansions,
// command substitutions and backticks recurse into their own sub-lists.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ExpKind {
    Var,
    Brace,
    CmdSub,
    Backtick,
    Arith,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum QKind {
    Single,
    Double,
    Ansi,
    Locale,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    Sep,
    Nl,
    Comment,
    Heredoc,
    Op,
    Lit,
    Esc,
    Exp(ExpKind),
    QOpen(QKind),
    QClose(QKind),
    QText,
}

#[derive(Clone, Debug)]
pub struct Tok {
    pub kind: Kind,
    pub text: String,
    pub sub: Vec<Tok>,
}

impl Tok {
    pub fn new(kind: Kind, text: &str) -> Tok {
        Tok { kind, text: text.to_string(), sub: Vec::new() }
    }
    pub fn new_sub(kind: Kind, text: &str, sub: Vec<Tok>) -> Tok {
        Tok { kind, text: text.to_string(), sub }
    }
}

#[derive(Debug)]
pub struct LexErr;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Stop {
    Eof,
    Paren,
    Backtick,
}

fn is_id_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == '\t'
}

fn is_op_start(c: char) -> bool {
    matches!(c, ';' | '|' | '&' | '<' | '>')
}

pub struct Lex {
    cs: Vec<char>,
    pos: usize,
}

impl Lex {
    pub fn new(src: &str) -> Lex {
        Lex { cs: src.chars().collect(), pos: 0 }
    }

    fn cur(&self) -> Option<char> {
        self.cs.get(self.pos).copied()
    }
    fn at(&self, n: usize) -> Option<char> {
        self.cs.get(self.pos + n).copied()
    }
    fn slice(&self, a: usize, b: usize) -> String {
        self.cs[a..b].iter().collect()
    }
    fn take(&mut self, n: usize) -> String {
        let s = self.slice(self.pos, self.pos + n);
        self.pos += n;
        s
    }

    pub fn top(&mut self) -> Result<Vec<Tok>, LexErr> {
        let mut out: Vec<Tok> = Vec::new();
        self.until(Stop::Eof, &mut out)?;
        Ok(out)
    }

    /// Parse tokens until the end of the region described by `stop`.
    /// Appends to `out`; the terminator itself is *not* consumed.
    fn until(&mut self, stop: Stop, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        let mut paren_depth: i32 = 0;
        loop {
            if self.pos >= self.cs.len() {
                if stop != Stop::Eof {
                    return Err(LexErr);
                }
                return Ok(());
            }
            let c = self.cur().unwrap();
            match c {
                '\n' => {
                    out.push(Tok::new(Kind::Nl, "\n"));
                    self.pos += 1;
                }
                '\r' if self.at(1) == Some('\n') => {
                    out.push(Tok::new(Kind::Nl, "\r\n"));
                    self.pos += 2;
                }
                c if is_ws(c) => {
                    let start = self.pos;
                    while self.pos < self.cs.len() && is_ws(self.cs[self.pos]) {
                        self.pos += 1;
                    }
                    out.push(Tok::new(Kind::Sep, &self.slice(start, self.pos)));
                }
                '#' => {
                    let start = self.pos;
                    while self.pos < self.cs.len() && self.cs[self.pos] != '\n' {
                        self.pos += 1;
                    }
                    out.push(Tok::new(Kind::Comment, &self.slice(start, self.pos)));
                }
                ';' | '|' | '&' | '<' | '>' => {
                    if let Some(op) = self.operator() {
                        out.push(Tok::new(Kind::Op, &op));
                        self.pos += op.chars().count();
                        if op == "<<" || op == "<<-" {
                            self.heredoc(&op, out)?;
                        }
                    } else {
                        return Err(LexErr);
                    }
                }
                '(' => {
                    paren_depth += 1;
                    out.push(Tok::new(Kind::Op, "("));
                    self.pos += 1;
                }
                ')' => {
                    if stop == Stop::Paren && paren_depth == 0 {
                        return Ok(());
                    }
                    if paren_depth > 0 {
                        paren_depth -= 1;
                    }
                    out.push(Tok::new(Kind::Op, ")"));
                    self.pos += 1;
                }
                '`' => {
                    if stop == Stop::Backtick {
                        return Ok(());
                    }
                    self.backtick(out)?;
                }
                '\\' => {
                    out.push(Tok::new(Kind::Esc, &self.take(2)));
                }
                '$' => {
                    self.dollar(stop, out)?;
                }
                '\'' => {
                    out.push(Tok::new(Kind::QOpen(QKind::Single), "'"));
                    self.pos += 1;
                    self.quoted(QKind::Single, out)?;
                    out.push(Tok::new(Kind::QClose(QKind::Single), "'"));
                    self.pos += 1;
                }
                '"' => {
                    out.push(Tok::new(Kind::QOpen(QKind::Double), "\""));
                    self.pos += 1;
                    self.quoted(QKind::Double, out)?;
                    out.push(Tok::new(Kind::QClose(QKind::Double), "\""));
                    self.pos += 1;
                }
                _ => {
                    // literal text
                    let start = self.pos;
                    while self.pos < self.cs.len() {
                        let ch = self.cs[self.pos];
                        if ch == '\n'
                            || ch == '\r'
                            || is_ws(ch)
                            || ch == '#'
                            || is_op_start(ch)
                            || ch == '('
                            || ch == ')'
                            || ch == '`'
                            || ch == '\\'
                            || ch == '$'
                            || ch == '\''
                            || ch == '"'
                        {
                            break;
                        }
                        self.pos += 1;
                    }
                    if self.pos == start {
                        return Err(LexErr);
                    }
                    out.push(Tok::new(Kind::Lit, &self.slice(start, self.pos)));
                }
            }
        }
    }

    fn operator(&self) -> Option<&'static str> {
        let s3: String = self.slice(self.pos, (self.pos + 3).min(self.cs.len()));
        let s2: String = self.slice(self.pos, (self.pos + 2).min(self.cs.len()));
        let c = self.cur()?;
        Some(match c {
            '<' => {
                if s3.starts_with("<<<") {
                    "<<<"
                } else if s3.starts_with("<<-") {
                    "<<-"
                } else if s2.starts_with("<<") {
                    "<<"
                } else if s2.starts_with("<&") {
                    "<&"
                } else {
                    "<"
                }
            }
            '>' => {
                if s2.starts_with(">>") {
                    ">>"
                } else if s2.starts_with(">&") {
                    ">&"
                } else {
                    ">"
                }
            }
            ';' => {
                if s3.starts_with(";;&") {
                    ";;&"
                } else if s2.starts_with(";;") {
                    ";;"
                } else {
                    ";"
                }
            }
            '|' => {
                if s2.starts_with("||") {
                    "||"
                } else if s2.starts_with("|&") {
                    "|&"
                } else {
                    "|"
                }
            }
            '&' => {
                if s2.starts_with("&&") {
                    "&&"
                } else {
                    "&"
                }
            }
            _ => return None,
        })
    }

    /// Handle a heredoc start that was just emitted as an `<<`/`<<-` operator.
    fn heredoc(&mut self, op: &str, out: &mut Vec<Tok>) -> Result<(), LexErr> {
        let char_start = self.pos - op.chars().count();
        let out_start = out.len() - 1;
        // look ahead for a delimiter token
        let mut p = self.pos;
        while p < self.cs.len() && (is_ws(self.cs[p]) || self.cs[p] == '\n') {
            p += 1;
        }
        if p >= self.cs.len() {
            // no delimiter: not a heredoc
            return Ok(());
        }
        // consume whitespace / newlines as tokens, they will be merged
        while self.pos < self.cs.len() && (is_ws(self.cs[self.pos]) || self.cs[self.pos] == '\n') {
            let c = self.cs[self.pos];
            if c == '\n' {
                out.push(Tok::new(Kind::Nl, "\n"));
            } else {
                let start = self.pos;
                while self.pos < self.cs.len() && is_ws(self.cs[self.pos]) {
                    self.pos += 1;
                }
                out.push(Tok::new(Kind::Sep, &self.slice(start, self.pos)));
            }
        }
        // parse the delimiter token group
        let mut del: Vec<Tok> = Vec::new();
        match self.cur() {
            Some('\'') => {
                del.push(Tok::new(Kind::QOpen(QKind::Single), "'"));
                self.pos += 1;
                self.quoted(QKind::Single, &mut del)?;
                del.push(Tok::new(Kind::QClose(QKind::Single), "'"));
                self.pos += 1;
            }
            Some('"') => {
                del.push(Tok::new(Kind::QOpen(QKind::Double), "\""));
                self.pos += 1;
                self.quoted(QKind::Double, &mut del)?;
                del.push(Tok::new(Kind::QClose(QKind::Double), "\""));
                self.pos += 1;
            }
            Some('$') => {
                self.dollar(Stop::Eof, &mut del)?;
            }
            Some('`') => {
                self.backtick(&mut del)?;
            }
            Some('\\') => {
                del.push(Tok::new(Kind::Esc, &self.take(2)));
            }
            Some('#') => {
                let start = self.pos;
                while self.pos < self.cs.len() && self.cs[self.pos] != '\n' {
                    self.pos += 1;
                }
                del.push(Tok::new(Kind::Comment, &self.slice(start, self.pos)));
            }
            _ => {
                let start = self.pos;
                while self.pos < self.cs.len() {
                    let ch = self.cs[self.pos];
                    if ch == '\n'
                        || ch == '\r'
                        || is_ws(ch)
                        || ch == '#'
                        || is_op_start(ch)
                        || ch == '('
