            '<' => {
                if s3.starts_with("<<<") {
                    "<<<"
                } else if s3.starts_with("<<-") {
                    "<<-"
                } else if s2.starts_with("<<") {
                    "<<"
                } else if s2.starts_with("<&") {
                    "<&"
                } else {
                    "<"
                }
            }
            '>' => {
                if s2.starts_with(">>") {
                    ">>"
                } else if s2.starts_with(">&") {
                    ">&"
                } else {
                    ">"
                }
            }
            ';' => {
                if s3.starts_with(";;&") {
                    ";;&"
                } else if s2.starts_with(";;") {
                    ";;"
                } else {
                    ";"
                }
            }
            '|' => {
                if s2.starts_with("||") {
                    "||"
                } else if s2.starts_with("|&") {
                    "|&"
                } else {
                    "|"
                }
            }
            '&' => {
                if s2.starts_with("&&") {
                    "&&"
                } else {
                    "&"
