// Highlighter and corrective transformer.

use crate::lex::*;
use crate::style::*;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Reg {
    Paren,
    Brace,
    Case { pattern: bool },
    Arith { open: i32, close: i32 },
    Test { open: i32, close: i32 },
    Array,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum CmdWord {
    Test,       // `test `
    Bracket,    // `[ `
    Decl,       // local/declare/export/readonly
}

fn is_id_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn is_ws(c: char) -> bool {
    c == ' ' || c == '\t'
}

fn is_sep_tok(t: &Tok) -> bool {
    matches!(t.kind, Kind::Sep | Kind::Nl | Kind::Comment | Kind::Heredoc)
}

fn is_boundary(t: &Tok) -> bool {
    is_sep_tok(t) || t.kind == Kind::Op
}

pub struct Proc {
    pub out: Vec<Out>,
    cmd_start: bool,
    assign_mode: bool,
    cmd_word: Option<CmdWord>,
    for_head: bool,
    case_head: bool,
    regs: Vec<Reg>,
    had_sep: bool,
    sep_after_cmd: bool,
}

impl Proc {
    pub fn new() -> Proc {
        Proc {
            out: Vec::new(),
            cmd_start: true,
            assign_mode: true,
            cmd_word: None,
            for_head: false,
            case_head: false,
            regs: Vec::new(),
            had_sep: true,
            sep_after_cmd: false,
        }
    }

    fn push(&mut self, text: &str, style: Style, change: Change) {
        if text.is_empty() {
            return;
        }
        self.out.push(Out { text: text.to_string(), style, change });
    }

    // ---------- helpers on token sequences ----------

    /// find the matching QClose for a QOpen at index `i`, or None
    fn qmatch(parts: &[Tok], i: usize) -> Option<usize> {
        let qk = match parts[i].kind {
            Kind::QOpen(k) => k,
            _ => return None,
        };
        let mut depth = 0;
        let mut j = i + 1;
        while j < parts.len() {
            match parts[j].kind {
                Kind::QOpen(k) if k == qk => depth += 1,
                Kind::QClose(k) if k == qk => {
                    if depth == 0 {
                        return Some(j);
                    }
                    depth -= 1;
                }
                _ => {}
            }
            j += 1;
        }
        None
    }

    /// Is the token at index i inside a quoted region (of the given kind)?
    fn in_quote(parts: &[Tok], i: usize) -> Option<QKind> {
        let mut j = 0;
        let mut res = None;
        while j < parts.len() {
            if let Some(e) = Proc::qmatch(parts, j) {
                if i >= j && i <= e {
                    // nested?
                    if let Some(inner) = Proc::in_quote(&parts[j + 1..e], i - j - 1) {
                        res = Some(inner);
                    } else {
                        res = Some(match parts[j].kind {
                            Kind::QOpen(k) => k,
                            _ => unreachable!(),
                        });
                    }
                    return res;
                }
                j = e + 1;
            } else {
                j += 1;
            }
        }
        None
    }

    fn expansion_needs_quote(t: &Tok) -> bool {
        match &t.kind {
            Kind::Exp(ExpKind::Var) => {
                let name: Vec<char> = t.text.chars().skip(1).collect();
                match name.first() {
                    Some(c) => !matches!(c, '?' | '!' | '$' | '#'),
                    None => false,
                }
            }
            Kind::Exp(ExpKind::Brace) => {
                let content: Vec<char> = t.text.chars().skip(2).take(t.text.chars().count() - 3).collect();
                match content.first() {
                    Some(c) => !matches!(c, '?' | '!' | '$' | '#'),
                    None => true,
                }
            }
            Kind::Exp(ExpKind::CmdSub) | Kind::Exp(ExpKind::Backtick) => true,
            _ => false,
        }
    }

    fn absorbable(parts: &[Tok], i: usize) -> bool {
        let t = &parts[i];
        match &t.kind {
            Kind::Exp(_) => Proc::in_quote(parts, i).is_none(),
            Kind::QOpen(QKind::Double) => true,
            _ => false,
        }
    }

    /// Determine the first character that would be emitted by the part at
    /// index i (assuming the part itself is emitted normally).
    fn first_emitted(parts: &[Tok], i: usize) -> Option<char> {
        let t = &parts[i];
        match &t.kind {
            Kind::Lit(s) | Kind::QText(s) | Kind::Comment(s) => s.chars().next(),
            Kind::Sep(s) => s.chars().next(),
            Kind::Nl => Some('\n'),
            Kind::Esc(_) => Some('\\'),
            Kind::Op(_) => t.text.chars().next(),
            Kind::Heredoc(_) => t.text.chars().next(),
            Kind::Exp(ExpKind::Var) | Kind::Exp(ExpKind::Arith) | Kind::Exp(ExpKind::CmdSub) | Kind::Exp(ExpKind::Brace) => {
                Some('$')
            }
            Kind::Exp(ExpKind::Backtick) => Some('`'),
            Kind::QOpen(QKind::Ansi) | Kind::Exp(_) => Some('$'),
            Kind::QOpen(QKind::Single) => Some('\''),
            Kind::QOpen(QKind::Double) | Kind::QOpen(QKind::Locale) => {
                // if the region is absorbed, the first emitted char is the
                // first char of the content
                if let Some(e) = Proc::qmatch(parts, i) {
                    if e == i + 1 {
                        Some('"')
                    } else {
                        Proc::first_emitted(parts, i + 1)
                    }
                } else {
                    Some('"')
                }
            }
            Kind::QClose(_) => t.text.chars().next(),
        }
    }

    // ---------- main ----------

    pub fn list(&mut self, toks: &[Tok]) {
        let mut i = 0;
        while i < toks.len() {
            let t = &toks[i];
            if is_boundary(t) {
                if let Some(consumed) = self.boundary(&toks[i..]) {
                    i += consumed;
                    continue;
                }
                i += 1;
                continue;
            }
            // start of a word: find its extent
            let mut j = i;
            while j < toks.len() && !is_boundary(&toks[j]) {
                j += 1;
            }
            self.word(&toks[i..j]);
            i = j;
        }
    }

    /// Handle a boundary token.  Returns how many tokens were consumed.
    fn boundary(&mut self, toks: &[Tok]) -> Option<usize> {
        let t = &toks[0];
        match &t.kind {
            Kind::Sep(s) => {
                let style = self.sep_style();
                self.push(s, style, Change::Same);
                self.had_sep = true;
                self.sep_after_cmd = false;
                Some(1)
            }
            Kind::Nl => {
                self.push(&t.text, Style::Plain, Change::Same);
                self.had_sep = true;
                self.cmd_start = true;
                self.assign_mode = true;
                self.for_head = false;
                self.sep_after_cmd = false;
                Some(1)
            }
            Kind::Comment(s) => {
                self.push(s, Style::Comment, Change::Same);
                self.had_sep = true;
                self.cmd_start = true;
                self.assign_mode = true;
                self.for_head = false;
                self.sep_after_cmd = false;
                Some(1)
            }
            Kind::Heredoc(s) => {
                self.push(s, Style::Heredoc, Change::Same);
                self.had_sep = true;
                self.sep_after_cmd = false;
                Some(1)
            }
            Kind::Op(op) => {
                self.op(toks)
            }
            _ => None,
        }
    }

    fn sep_style(&self) -> Style {
        if let Some(r) = self.regs.last() {
            match r {
                Reg::Test { .. } | Reg::Arith { .. } => return Style::Arith,
                Reg::Case { .. } => {}
                _ => {}
            }
        }
        if self.case_head {
            return Style::Keyword;
        }
        if self.for_head {
            return Style::Keyword;
        }
        if self.sep_after_cmd {
            return Style::Command;
        }
        Style::Plain
    }
}
RSEOF
echo ok"}

