// ---------------- operators ----------------

impl Proc {
    fn in_arith(&self) -> bool {
        matches!(self.regs.last(), Some(Reg::Arith { .. }))
    }
    fn in_test(&self) -> bool {
        matches!(self.regs.last(), Some(Reg::Test { .. }))
    }

    fn op_style(&self) -> Style {
        if self.in_arith() || self.in_test() {
            Style::Arith
        } else if self.case_head {
            Style::Keyword
        } else if self.for_head {
            Style::Keyword
        } else {
            Style::Plain
        }
    }

    fn current_style(&self) -> Style {
        self.op_style()
    }

    fn op(&mut self, toks: &[Tok]) -> Option<usize> {
        let t = &toks[0];
        let op = t.text.clone();
        match op.as_str() {
            "(" => {
                if self.cmd_start && !self.in_arith() && !self.in_test() {
                    if toks.len() > 1 && toks[1].kind == Kind::Op && toks[1].text == "(" {
                        self.push("(", Style::Arith, Change::Same);
                        self.push("(", Style::Arith, Change::Same);
                        self.regs.push(Reg::Arith { open: 2, close: 0 });
                        self.cmd_start = false;
                        return Some(2);
                    }
                    self.push("(", Style::Plain, Change::Same);
                    self.regs.push(Reg::Paren);
                    self.cmd_start = true;
                    self.assign_mode = true;
                    self.for_head = false;
                    self.case_head = false;
                    self.had_sep = true;
                    return Some(1);
                }
                self.push("(", self.op_style(), Change::Same);
                if self.in_arith() {
                    if let Some(Reg::Arith { open, .. }) = self.regs.last_mut() {
                        *open += 1;
                    }
                }
                Some(1)
            }
            ")" => {
                if self.in_arith() {
                    self.push(")", Style::Arith, Change::Same);
                    if let Some(Reg::Arith { open, close }) = self.regs.last_mut() {
                        *close += 1;
                        if *close >= *open {
                            self.regs.pop();
                        }
                    }
                    return Some(1);
                }
                if self.in_test() {
                    self.push(")", self.op_style(), Change::Same);
                    return Some(1);
                }
                match self.regs.last() {
                    Some(Reg::Paren) => {
                        self.push(")", Style::Plain, Change::Same);
                        self.regs.pop();
                        self.cmd_start = true;
                        self.assign_mode = true;
                        self.had_sep = true;
                        Some(1)
                    }
                    Some(Reg::Case { pattern }) => {
                        if *pattern {
                            self.push(")", Style::Plain, Change::Same);
                            if let Some(Reg::Case { pattern }) = self.regs.last_mut() {
                                *pattern = false;
                            }
                            self.cmd_start = true;
                            self.assign_mode = true;
                            self.had_sep = true;
                            Some(1)
                        } else {
                            self.close_paren_like(op.as_str())
                        }
                    }
                    Some(Reg::Array) => {
                        self.push(")", Style::Plain, Change::Same);
                        self.regs.pop();
                        Some(1)
                    }
                    _ => self.close_paren_like(op.as_str()),
                }
            }
            ";" | ";;" | "|&" | "&&" | "||" | "|" | "&" => {
                self.push(&op, self.op_style(), Change::Same);
                self.cmd_start = true;
                self.assign_mode = true;
                self.for_head = false;
                self.sep_after_cmd = false;
                self.had_sep = true;
                Some(1)
            }
            _ => {
                self.push(&op, self.op_style(), Change::Same);
                Some(1)
            }
        }
    }

    fn close_paren_like(&mut self, op: &str) -> Option<usize> {
        if self.cmd_start {
            self.push(op, Style::Command, Change::Same);
        } else {
            self.push(op, Style::Plain, Change::Same);
        }
        Some(1)
    }
}
