// ---------------- words ----------------

const KEYWORDS: &[&str] = &[
    "if", "then", "elif", "else", "fi", "for", "while", "until", "case", "esac", "do", "done",
    "function", "select", "!", "{", "}", "local", "declare", "export", "readonly",
];

const DECL_KEYWORDS: &[&str] = &["local", "declare", "export", "readonly"];

fn valid_assign_name(s: &str) -> bool {
    let cs: Vec<char> = s.chars().collect();
    if cs.is_empty() {
        return false;
    }
    if !(cs[0].is_alphabetic() || cs[0] == '_') {
        return false;
    }
    let mut i = 1;
    while i < cs.len() {
        if cs[i].is_alphanumeric() || cs[i] == '_' {
            i += 1;
        } else if cs[i] == '[' {
            i += 1;
            while i < cs.len() && cs[i] != ']' {
                i += 1;
            }
            if i >= cs.len() {
                return false;
            }
            i += 1;
        } else {
            return false;
        }
    }
    true
}

impl Proc {
    fn split_assign(parts: &[Tok]) -> Option<(usize, usize)> {
        let mut acc = String::new();
        for (i, t) in parts.iter().enumerate() {
            match &t.kind {
                Kind::Lit(s) => {
                    if let Some(p) = s.find('=') {
                        acc.push_str(&s[..p]);
                        if valid_assign_name(&acc) {
                            return Some((i, p));
                        }
                        return None;
                    }
                    acc.push_str(s);
                }
                Kind::Exp(_) | Kind::Esc(_) | Kind::QOpen(_) | Kind::QClose(_) | Kind::QText(_) => {
                    acc.push_str(&t.text);
                }
                _ => return None,
            }
        }
        None
    }

    fn whole_keyword(parts: &[Tok]) -> Option<&'static str> {
        if parts.len() != 1 {
            return None;
        }
        if parts[0].kind != Kind::Lit {
            return None;
        }
        let t = parts[0].text.as_str();
        KEYWORDS.iter().copied().find(|k| *k == t)
    }
}
