// ---------------- word emission ----------------

impl Proc {
    fn xform(&self) -> bool {
        if self.in_arith() || self.in_test() {
            return false;
        }
        if self.case_head {
            return false;
        }
        true
    }

    fn word(&mut self, parts: &[Tok], after: &[Tok]) {
        if self.cmd_start {
            if let Some((eq_i, eq_p)) = Proc::split_assign(parts) {
                self.emit_assign(parts, eq_i, eq_p);
                return;
            }
            self.command_word(parts, after);
            return;
        }
        if self.for_head {
            self.for_head_word(parts, after);
            return;
        }
        if self.case_head {
            // the word is part of the case head
            if parts.len() == 1 && parts[0].kind == Kind::Lit && parts[0].text == "in" {
                self.push("in", Style::Keyword, Change::Same);
                self.case_head = false;
                self.had_sep = true;
                return;
            }
            self.emit_word(parts, Style::Keyword, false);
            return;
        }
        self.emit_word(parts, Style::Plain, self.xform());
    }

    fn for_head_word(&mut self, parts: &[Tok], after: &[Tok]) {
        // in the for head, plain identifier words are loop variables
        if parts.len() == 1 && parts[0].kind == Kind::Lit {
            let s = parts[0].text.as_str();
            if s == "in" {
                self.push("in", Style::Keyword, Change::Same);
                self.for_head = false;
                self.had_sep = true;
                return;
            }
            // longest identifier prefix
            let chars: Vec<char> = s.chars().collect();
            let mut n = 0;
            if chars[0].is_alphabetic() || chars[0] == '_' {
                n = 1;
                while n < chars.len() && (chars[n].is_alphanumeric() || chars[n] == '_') {
                    n += 1;
                }
            }
            let id: String = chars[..n].iter().collect();
            let rest: String = chars[n..].iter().collect();
            if n == chars.len() {
                self.push(&id, Style::VarName, Change::Same);
                return;
            }
            // the for head ends here
            self.for_head = false;
            if !id.is_empty() {
                self.push(&id, Style::VarName, Change::Same);
            }
            self.push(&rest, Style::Command, Change::Same);
            self.cmd_start = false;
            self.had_sep = true;
            return;
        }
        // not an identifier word: the for head ends
        self.for_head = false;
        self.emit_word(parts, Style::Command, true);
        self.cmd_start = false;
        self.had_sep = true;
    }

    fn command_word(&mut self, parts: &[Tok], after: &[Tok]) {
        // function definition  `name()`
        if !self.in_arith() && !self.in_test() && !self.case_head {
            if after.len() >= 2 && after[0].kind == Kind::Op && after[0].text == "("
                && after[1].kind == Kind::Op && after[1].text == ")"
            {
                self.emit_word(parts, Style::Command, true);
                self.push("(", Style::Plain, Change::Same);
                self.push(")", Style::Plain, Change::Same);
                self.cmd_start = true;
                self.assign_mode = true;
                self.had_sep = true;
                return;
            }
        }
        // `[[` test region
        if !self.in_arith() && !self.in_test() {
            if parts.len() == 1 && parts[0].kind == Kind::Lit && parts[0].text == "[[" {
                let nxt = after.first();
                let ok = match nxt {
                    Some(t) => matches!(t.kind, Kind::Sep | Kind::Nl),
                    None => true,
                };
                if ok {
                    self.push("[[", Style::Arith, Change::Same);
                    self.regs.push(Reg::Test { open: 2, close: 0 });
                    self.cmd_start = false;
                    self.had_sep = true;
                    return;
                }
            }
        }
        let kw = Proc::whole_keyword(parts);
        if let Some(kw) = kw {
            self.push(&parts[0].text, Style::Keyword, Change::Same);
            match kw {
                "for" | "select" => {
                    self.for_head = true;
                    self.cmd_start = false;
                    self.had_sep = true;
                }
                "case" => {
                    self.case_head = true;
                    self.cmd_start = false;
                    self.had_sep = true;
                }
                _ => {
                    self.cmd_start = true;
                    self.assign_mode = DECL_KEYWORDS.contains(&kw);
                }
            }
            self.had_sep = true;
            return;
        }
        // `test ` / `[ `
        if parts.len() == 1 && parts[0].kind == Kind::Lit
            && (parts[0].text == "test" || parts[0].text == "[")
        {
            let cmdw = if parts[0].text == "test" { CmdWord::Test } else { CmdWord::Bracket };
            let nxt = after.first();
            let mut consumed = 1;
            let mut absorbed = false;
            if let Some(t) = nxt {
                if t.kind == Kind::Sep && t.text == " " {
                    absorbed = true;
                    consumed = 2;
                }
            }
            self.push(&parts[0].text, Style::Command, Change::Same);
            if absorbed {
                self.push(" ", Style::Command, Change::Same);
            }
            self.cmd_word = Some(cmdw);
            self.cmd_start = false;
            self.had_sep = true;
            self.sep_after_cmd = false;
            return;
