fn quote_style(k: QKind) -> Style {
    match k {
        QKind::Single => Style::SQuote,
        QKind::Double => Style::DQuote,
        QKind::Ansi => Style::Ansi,
        QKind::Locale => Style::DQuote,
    }
}

fn brace_content(text: &str) -> String {
    let n = text.chars().count();
    if n < 3 {
        return String::new();
    }
    text[2..n - 1].to_string()
}

fn removable_brace_name(content: &str) -> bool {
    let cs: Vec<char> = content.chars().collect();
    if cs.is_empty() {
        return false;
    }
    if cs.len() == 1 && cs[0].is_ascii_digit() {
        return true;
    }
    if !(cs[0].is_alphabetic() || cs[0] == '_') {
        return false;
    }
    cs.iter().all(|c| c.is_alphanumeric() || *c == '_')
}

/// If the content is of the form `<name>[*]`, return the position of `*`
/// (as a char offset within the content) and the length of `<name>`.
fn brace_star(content: &str) -> Option<(usize, usize)> {
    let cs: Vec<char> = content.chars().collect();
    if cs.len() < 4 {
        return None;
    }
    if cs[cs.len() - 2] != '[' || cs[cs.len() - 1] != '*' {
        return None;
    }
    let n = cs.len() - 2;
    if n == 0 {
        return None;
    }
    if !(cs[0].is_alphabetic() || cs[0] == '_') {
        return None;
    }
    let mut i = 1;
    while i < n {
        if !(cs[i].is_alphanumeric() || cs[i] == '_') {
            return None;
        }
        i += 1;
    }
    Some((cs.len() - 1, n))
}

impl Proc {
    fn first_emitted_at(parts: &[Tok], i: usize) -> Option<char> {
        if i >= parts.len() {
            return None;
        }
        Proc::first_emitted(parts, i)
    }

    fn compute_runs(parts: &[Tok]) -> Vec<(usize, usize)> {
        let mut runs: Vec<(usize, usize)> = Vec::new();
        let mut i = 0;
        while i < parts.len() {
            if Proc::in_quote(parts, i).is_none() && Proc::expansion_needs_quote(&parts[i]) {
                let start = i;
                let mut j = i + 1;
                while j < parts.len() && Proc::absorbable(parts, j) {
                    if matches!(parts[j].kind, Kind::QOpen(QKind::Double)) {
                        let e = Proc::qmatch(parts, j).unwrap();
                        j = e + 1;
                    } else {
                        j += 1;
                    }
                }
                runs.push((start, j));
                i = j;
            } else {
                i += 1;
            }
        }
        runs
    }

    fn rule_b_dels(parts: &[Tok]) -> Vec<usize> {
        let mut out: Vec<usize> = Vec::new();
        let mut i = 0;
        while i < parts.len() {
            if matches!(parts[i].kind, Kind::QOpen(QKind::Double) | Kind::QOpen(QKind::Locale)) {
                if let Some(e) = Proc::qmatch(parts, i) {
                    if e == i + 2 && matches!(parts[i + 1].kind, Kind::Exp(ExpKind::Brace)) {
                        let content = brace_content(&parts[i + 1].text);
                        if removable_brace_name(&content) {
                            let next = Proc::first_emitted_at(parts, e + 1);
                            if !next.map(is_id_char).unwrap_or(false) {
                                out.push(i + 1);
                            }
                        }
                    }
                    i = e + 1;
                    continue;
                }
            }
            i += 1;
        }
        out
    }

    fn emit_token(&mut self, parts: &[Tok], i: usize, lit_style: Style, xform: bool, dels: &[usize]) {
        let t = &parts[i];
        match &t.kind {
            Kind::Lit(s) => self.push(s, lit_style, Change::Same),
            Kind::QText(s) => {
                let qk = Proc::in_quote(parts, i).unwrap_or(QKind::Double);
                self.push(s, quote_style(qk), Change::Same);
            }
            Kind::QOpen(k) => self.push(&t.text, quote_style(*k), Change::Same),
            Kind::QClose(k) => self.push(&t.text, quote_style(*k), Change::Same),
            Kind::Esc(s) => self.push(s, Style::Escape, Change::Same),
            Kind::Exp(ExpKind::Var) => {
                if t.text == "$" {
                    self.push("$", Style::Plain, Change::Same);
                } else {
                    self.push(&t.text, Style::Var, Change::Same);
                }
            }
            Kind::Exp(ExpKind::Brace) => {
                if dels.contains(&i) {
                    let content = brace_content(&t.text);
                    self.push("$", Style::Var, Change::Same);
                    self.push("{", Style::Var, Change::Del);
                    self.push(&content, Style::Var, Change::Same);
                    self.push("}", Style::Var, Change::Del);
                } else {
                    self.push(&t.text, Style::Var, Change::Same);
                }
            }
            Kind::Exp(ExpKind::Arith) => self.push(&t.text, Style::Arith, Change::Same),
            Kind::Exp(ExpKind::CmdSub) => {
                self.push("$( ", Style::Plain, Change::Same);
                let sub = t.sub.clone();
                let mut p = Proc::new();
                p.list(&sub);
                self.out.extend(p.out);
                self.push(")", Style::Plain, Change::Same);
            }
            Kind::Exp(ExpKind::Backtick) => {
                if xform {
                    self.push("`", Style::Plain, Change::Del);
                    self.push("$(", Style::Plain, Change::Ins);
                    let sub = t.sub.clone();
                    let mut p = Proc::new();
                    p.list(&sub);
                    self.out.extend(p.out);
                    self.push("`", Style::Plain, Change::Del);
                    self.push(")", Style::Plain, Change::Ins);
                } else {
                    self.push("`", Style::Plain, Change::Same);
                    let sub = t.sub.clone();
                    let mut p = Proc::new();
                    p.list(&sub);
                    self.out.extend(p.out);
                    self.push("`", Style::Plain, Change::Same);
                }
            }
            _ => {}
        }
    }

    fn emit_run_token(&mut self, parts: &[Tok], i: usize, run_end: usize, lit_style: Style) {
        let t = &parts[i];
        match &t.kind {
            Kind::Exp(ExpKind::Var) => {
                let text = &t.text;
                if text == "$" {
                    self.push("$", Style::Plain, Change::Same);
                    return;
                }
                let name: String = text.chars().skip(1).collect();
                if name == "*" {
                    self.push("$", Style::Var, Change::Same);
                    self.push("*", Style::Var, Change::Del);
                    self.push("@", Style::Var, Change::Ins);
                    return;
                }
                let next = Proc::first_emitted_at(parts, i + 1);
                if next.map(is_id_char).unwrap_or(false) {
                    self.push("$", Style::Var, Change::Same);
                    self.push("{", Style::Var, Change::Ins);
                    self.push(&name, Style::Var, Change::Same);
                    self.push("}", Style::Var, Change::Ins);
                } else {
                    self.push(text, Style::Var, Change::Same);
                }
            }
            Kind::Exp(ExpKind::Brace) => {
                let content = brace_content(&t.text);
                if let Some((starpos, namelen)) = brace_star(&content) {
                    let name = &content[..namelen];
                    let before: String = content.chars().take(namelen).collect();
                    let _ = before;
                    self.push("$", Style::Var, Change::Same);
                    self.push("{", Style::Var, Change::Same);
                    self.push(name, Style::Var, Change::Same);
                    self.push("[", Style::Var, Change::Same);
                    self.push("*", Style::Var, Change::Del);
                    self.push("@", Style::Var, Change::Ins);
                    self.push("]", Style::Var, Change::Same);
                    self.push("}", Style::Var, Change::Same);
                    let _ = starpos;
                    return;
                }
                let next = Proc::first_emitted_at(parts, i + 1);
                let removable = removable_brace_name(&content);
                if removable && !next.map(is_id_char).unwrap_or(false) {
                    self.push("$", Style::Var, Change::Same);
                    self.push("{", Style::Var, Change::Del);
                    self.push(&content, Style::Var, Change::Same);
                    self.push("}", Style::Var, Change::Del);
                } else {
                    self.push(&t.text, Style::Var, Change::Same);
                }
            }
            Kind::QOpen(QKind::Double) => {
                self.push("\"", Style::DQuote, Change::Del);
            }
            _ => self.emit_token(parts, i, lit_style, true, &[]),
        }
    }

    fn emit_word(&mut self, parts: &[Tok], lit_style: Style, xform: bool) {
        let runs = if xform { Proc::compute_runs(parts) } else { Vec::new() };
        let dels = Proc::rule_b_dels(parts);
        let mut i = 0;
        while i < parts.len() {
            if let Some(&(s, e)) = runs.iter().find(|&&(s, _)| s == i) {
                self.push("\"", Style::Plain, Change::Ins);
                let mut j = s;
                while j < e {
                    self.emit_run_token(parts, j, e, lit_style);
                    j += 1;
                }
                self.push("\"", Style::Plain, Change::Ins);
                i = e;
            } else {
                self.emit_token(parts, i, lit_style, xform, &dels);
                i += 1;
            }
        }
    }

    fn emit_assign(&mut self, parts: &[Tok], eq_i: usize, eq_p: usize) {
        for i in 0..parts.len() {
            let t = &parts[i];
            if i < eq_i {
                self.emit_token(parts, i, Style::VarName, false, &[]);
            } else if i == eq_i {
                let chars: Vec<char> = t.text.chars().collect();
                let name: String = chars[..eq_p].iter().collect();
                let rest: String = chars[eq_p + 1..].iter().collect();
                if !name.is_empty() {
                    self.push(&name, Style::VarName, Change::Same);
                }
                self.push("=", Style::Plain, Change::Same);
                self.after_eq = true;
                if !rest.is_empty() {
                    let mut v = vec![Tok::new(Kind::Lit, &rest)];
                    self.emit_word(&v, Style::Plain, false);
                }
            } else {
                self.emit_token(parts, i, Style::Plain, false, &[]);
            }
        }
        self.cmd_start = true;
        self.had_sep = false;
    }
}
