mod hl;
mod lex;
mod style;

use hl::Proc;
use lex::Lex;
use style::{Change, Out, Style};

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    Syntax,
    Suggest,
    SyntaxSuggest,
    Transform,
    Check,
    Replace,
}

const HELP: &str = "Shellharden: The corrective bash syntax highlighter.

Usage:
\tshellharden [options] [files]
\tcat files | shellharden [options] ''

Shellharden is a syntax highlighter and a tool to semi-automate the rewriting
of scripts to ShellCheck conformance, mainly focused on quoting.

The default mode of operation is like `cat`, but with syntax highlighting in
foreground colors and suggestive changes in background colors.

Options:
\t--suggest         Output a colored diff suggesting changes.
\t--syntax          Output syntax highlighting with ANSI colors.
\t--syntax-suggest  Diff with syntax highlighting (default mode).
\t--transform       Output suggested changes.
\t--check           No output; exit with 2 if changes are suggested.
\t--replace         Replace file contents with suggested changes.
\t--                Don't treat further arguments as options.
\t-h|--help         Show help text.
\t--version         Show version.

The changes suggested by Shellharden inhibits word splitting and indirect
pathname expansion. This will make your script ShellCheck compliant in terms of
quoting. Whether your script will work afterwards is a different question:
If your script was using those features on purpose, it obviously won't anymore!

Every script is possible to write without using word splitting or indirect
pathname expansion, but it may involve doing things differently.
See the accompanying file how_to_do_things_safely_in_bash.md or online:
https://github.com/anordal/shellharden/blob/master/how_to_do_things_safely_in_bash.md
";

fn render(out: &[Out], mode: Mode) -> (String, bool) {
    let mut s = String::new();
    let mut cur: Option<&'static str> = None;
    let mut changed = false;
    for a in out {
        if a.change != Change::Same {
            changed = true;
        }
        let key: Option<&'static str> = match mode {
            Mode::Syntax => {
                if a.change == Change::Ins {
                    continue;
                }
                if a.style == Style::Plain {
                    None
                } else {
                    Some(a.style.sgr())
                }
            }
            Mode::Transform | Mode::Check | Mode::Replace => {
                if a.change == Change::Del {
                    continue;
                }
                None
            }
            Mode::Suggest => {
                if a.change == Change::Same {
                    None
                } else if a.change == Change::Ins {
                    Some("0;42")
                } else {
                    Some("0;41")
                }
            }
            Mode::SyntaxSuggest => {
                if a.change == Change::Same {
                    if a.style == Style::Plain {
                        None
                    } else {
                        Some(a.style.sgr())
                    }
                } else if a.change == Change::Ins {
                    Some("0;42")
                } else {
                    Some("0;41")
                }
            }
        };
        if key != cur {
            if cur.is_some() {
                s.push_str("\x1b[m");
            }
            if let Some(k) = key {
                s.push_str("\x1b[");
                s.push_str(k);
                s.push('m');
            }
            cur = key;
        }
        if !matches!(mode, Mode::Check | Mode::Replace) {
            s.push_str(&a.text);
        }
    }
    if cur.is_some() {
        s.push_str("\x1b[m");
    }
    (s, changed)
}

fn process(src: &str) -> Result<Vec<Out>, ()> {
    let mut lx = Lex::new(src);
    let toks = lx.top().map_err(|_| ())?;
    let mut p = Proc::new();
    p.list(&toks);
    Ok(p.out)
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut mode = Mode::SyntaxSuggest;
    let mut files: Vec<String> = Vec::new();
    let mut no_more_opts = false;
    for a in args {
        if !no_more_opts {
            match a.as_str() {
                "--suggest" => {
                    mode = Mode::Suggest;
                    continue;
                }
                "--syntax" => {
                    mode = Mode::Syntax;
                    continue;
                }
                "--syntax-suggest" => {
                    mode = Mode::SyntaxSuggest;
                    continue;
                }
                "--transform" => {
                    mode = Mode::Transform;
                    continue;
                }
                "--check" => {
                    mode = Mode::Check;
                    continue;
                }
                "--replace" => {
                    mode = Mode::Replace;
                    continue;
                }
                "--" => {
                    no_more_opts = true;
                    continue;
                }
                "-h" | "--help" => {
                    print!("{}", HELP);
                    continue;
                }
                "--version" => {
                    println!("4.3.1");
                    continue;
                }
                _ => {
                    if a.starts_with('-') && a.len() > 1 {
                        eprintln!("{}: No such option.", a);
                        std::process::exit(3);
                    }
                }
            }
        }
        files.push(a);
    }

    let mut had_parse_err = false;
    let mut had_io_err = false;
    let mut suggested = false;
    for f in &files {
        let content = if f.is_empty() {
            use std::io::Read;
            let mut s = String::new();
            match std::io::stdin().read_to_string(&mut s) {
                Ok(_) => s,
                Err(e) => {
                    eprintln!("{}: {}", f, e);
                    had_io_err = true;
                    continue;
                }
            }
        } else {
            match std::fs::read_to_string(f) {
                Ok(s) => s,
                Err(e) => {
                    eprintln!("{}: {}", f, e);
                    had_io_err = true;
                    continue;
                }
            }
        };
        match process(&content) {
            Ok(out) => {
                let (text, changed) = render(&out, mode);
                if changed {
                    suggested = true;
                }
                match mode {
                    Mode::Check => {}
                    Mode::Replace => {
                        if changed {
                            if std::fs::write(f, &text).is_err() {
                                eprintln!("{}: cannot write file", f);
                                had_io_err = true;
                            }
                        }
                    }
                    _ => {
                        print!("{}", text);
                    }
                }
            }
            Err(()) => {
                had_parse_err = true;
                eprintln!("{}: Unexpected end of file", f);
                eprintln!("The file's end was reached without closing all sytactic scopes.");
                eprintln!("Either, the parser got lost, or the file is truncated or malformed.");
            }
        }
    }
    if had_io_err || had_parse_err {
        std::process::exit(if matches!(mode, Mode::Check) { 2 } else { 1 });
    }
    if matches!(mode, Mode::Check) && suggested {
        std::process::exit(2);
    }
    std::process::exit(0);
}
RSEOF
