new = '''    fn split_assign(parts: &[Tok]) -> Option<(usize, usize)> {
        let mut acc = String::new();
        for (i, t) in parts.iter().enumerate() {
            match &t.kind {
                Kind::Lit => {
                    let s = &t.text;
                    let mut p: Option<usize> = None;
                    for (k, c) in s.char_indices() {
                        if c == '=' {
                            p = Some(k);
                            break;
                        }
                        if c == '+' && s[k + 1..].starts_with('=') {
                            p = Some(k + 1);
                            break;
                        }
                    }
                    match p {
                        Some(p) => {
                            acc.push_str(&s[..p]);
                            if valid_assign_name(&acc) {
                                return Some((i, p));
                            }
                            return None;
                        }
                        None => acc.push_str(s),
                    }
                }
                Kind::Exp(_) | Kind::Esc | Kind::QOpen(_) | Kind::QClose(_) | Kind::QText => {
                    acc.push_str(&t.text);
                }
                _ => return None,
            }
        }
        None
    }

